def eraseOverlapIntervals(self, intervals: list[list[int]]) -> int:
    intervals.sort(key=lambda iv: iv[0])
    n = len(intervals)
    dp = [1] * n
    best = 0
    for i in range(n):
        for j in range(i):
            if intervals[j][1] <= intervals[i][0]:
                dp[i] = max(dp[i], dp[j] + 1)
        best = max(best, dp[i])
    return n - best

